        public async Task<bool> IsAllowedForLeaveAsync(int userId)
        {
            var ptoCustIds = GetPtoCustomerIds();
            var query = from cp in _db.ContractorPlacements
                        join p in _db.Profiles on cp.Id equals p.ContractorPlacementId
                        where p.Id == RecentProfile(cp.Id)
                           && p.EmploymentTypeId == 4
                           && cp.ContractorId == userId
                           && ptoCustIds.Contains(cp.CustomerId)
                        select cp.Id;

            return await query.Distinct().AnyAsync();
        }

        private List<int> GetPtoCustomerIds()
        {
            // Simulate fetching and processing configuration
            var configValue = "847"; // Example config value
            return configValue.Split(',').Select(int.Parse).Where(id => id > 0).ToList();
        }

        private int RecentProfile(int contractorPlacementId)
        {
            // Simulate fetching the most recent profile ID
            return _db.Profiles.Where(p => p.ContractorPlacementId == contractorPlacementId)
                               .OrderByDescending(p => p.CreatedAt)
                               .Select(p => p.Id)
                               .FirstOrDefault();
        }
    }
